BEGIN; CREATE TABLE log(op TEXT,r INTEGER,i INTEGER,t TEXT); CREATE TABLE t4(rowid INTEGER PRIMARY KEY,i INTEGER,t TEXT); CREATE TRIGGER t4_trigger1 AFTER INSERT ON t4 BEGIN INSERT INTO log VALUES('INSERT INTO t4',new.rowid,new.i,new.t); END; CREATE TRIGGER t4_trigger2 AFTER UPDATE ON t4 BEGIN INSERT INTO log VALUES('UPDATE OF t4',new.rowid,new.i,new.t); END; CREATE TRIGGER t4_trigger3 AFTER DELETE ON t4 BEGIN INSERT INTO log VALUES('DELETE OF t4',old.rowid,old.i,old.t); END; WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<9999) INSERT INTO t4(rowid,i,t) SELECT n,n,'number-'||n FROM c; UPDATE t4 SET i=rowid*2,t='number-'||(rowid*2) WHERE rowid%2=1; COMMIT;